    "ingestedAt": "07/11/2026 às 19:30",
    "imageUrl": "https://imagens.ebc.com.br/cNs0ifV4btWV3IpJC6w7gdtBBjs=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/11/06/oprojeto2.jpg?itok=DbejFDTw",
