    "category": "Governo",
    "ingestedAt": "07/11/2026 às 01:55",
    "imageUrl": "https://imagens.ebc.com.br/1FjeVfLI7qtiunOfTU76BHRKA40=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/11/06/0d7a2888.jpg.jpeg?itok=JRS9RoXp",
    "imageCaption": "Lula apresentará avanços ambientais na COP31, na Turquia",
